"use client";
import Link from "next/link";
import { FormEvent, useCallback, useEffect, useMemo, useRef, useState, type KeyboardEvent as ReactKeyboardEvent, type ReactNode } from "react";
import { api, createSessionWriteRegistry, ErpApiError, isHistorySessionRestore, sessionPost } from "../../public/erp/api-client.js";
import { roleLabel,statusLabel } from "../../public/erp/status-localization.js";
import "./planning.css";

type User={username:string;display_name:string;role:string;permissions:string[]};type Session={authenticated:boolean;user:User|null;csrf_token?:string};
type Candidate={product_id:number;product_code:string;product_name:string;product_version_id:number;product_version_code:string;bom_header_id:number;bom_code:string;bom_version_id:number;bom_version_code:string;bom_line_count:number};
type UnitOption={id:number;code:string;name:string};
type Resolution={requirement_item_id:number;line_no:number;provisional_name:string;quantity:string;unit_id:number|null;unit_pending:boolean;unit_code?:string;specification_requirement:string;product_id?:number;product_version_id?:number;bom_header_id?:number;bom_version_id?:number;unit_resolution_id?:number|null;unit_resolution_version_no?:number|null;unit_resolution_head_version?:number|null;resolved_unit_id?:number|null;resolved_unit_code?:string|null;resolved_unit_name?:string|null;unit_resolution_source_type?:"ENGINEERING_CONFIRMED"|"REQUIREMENT_DECLARED"|null};
type ResolutionData={project:{id:number;project_code:string;project_name:string;project_owner:string;version:number;requirement_version_id:number};rows:Resolution[];candidates:Candidate[];enabled_units:UnitOption[]};
type PackageRow={id:number;project_id:number;project_code:string;project_name:string;customer_name:string;package_version_no:number;status:string;version:number;package_digest:string;item_count:number;previous_package_id?:number|null;responds_to_return_event_id?:number|null;revision_response_version_id?:number|null;return_reason?:string;submitted_at?:string;returned_at?:string;accepted_at?:string;updated_at?:string};
type BomLine={id:number;material_id:number;line_no:number;quantity_per:string;loss_rate:string;calculated_gross_quantity:string;unit_id:number;unit_code:string;unit_name:string;specification_snapshot:Record<string,unknown>;material_digest:string};
type CreationValidation={outcome:"PASSED";evidence_source:"PACKAGE_CREATION_SERVICE_GATE";product_required_status:"ACTIVE";product_version_required_status:"RELEASED";bom_required_status:"ACTIVE";bom_version_required_status:"RELEASED"};
type PackageItem={id:number;line_no:number;provisional_name:string;required_quantity:string;source_unit_id:number|null;source_unit_pending:boolean;source_unit_code?:string|null;source_unit_name?:string|null;unit_id:number;unit_code:string;unit_name:string;unit_resolution_id:number;unit_resolution_version_no:number;unit_resolution_source_type:string;resolved_unit_id:number;product_id:number;product_version_id:number;product_code:string;product_name:string;product_version_code:string;product_current_status:string;product_version_current_status:string;bom_header_id:number;bom_version_id:number;bom_code:string;bom_version_code:string;bom_current_status:string;bom_version_current_status:string;creation_validation:CreationValidation;bom_lines:BomLine[]};
type TraceEvent={id:string;action:"CREATE"|"SUBMIT"|"RESUBMIT"|"RETURN"|"ACCEPT";actor:string;occurred_at:string;request_id:string|null;result:"SUCCESS"|"TRACE_INCOMPLETE";reason:string;evidence_source:string};
type RevisionContext={return_event_id:number;return_actor:string;return_reason:string;return_request_id:string;return_created_at:string;response_head_version:number|null;revision_response_version_id:number|null;response_version_no:number|null;response_text:string|null;response_text_digest:string|null;response_created_by:string|null;response_created_at:string|null;response_request_id:string|null;successor_package_id:number|null;successor_package_version_no:number|null;successor_status:string|null};
type LineageContext={previous_package_id:number;previous_package_version_no:number;previous_package_status:string;previous_package_digest:string;return_event_id:number;return_actor:string;return_reason:string;return_request_id:string;return_created_at:string;revision_response_version_id:number;response_version_no:number;response_text:string;response_text_digest:string;response_created_by:string;response_created_at:string;response_request_id:string;current_response_head_version:number|null};
type PackageDetail={header:PackageRow&{project_goal:string;project_owner:string;customer_code:string;customer_name:string;customer_requirement_summary:string;prepared_by:string;prepared_at:string;submitted_by?:string;returned_by?:string;accepted_by?:string};responsibility:{queue_role:"PLANNING"|"ENGINEERING_PROJECT"|"COMPLETED";assignee:null;handling_deadline:null};traceability:{complete:boolean;creation_request_source:string|null;transition_source:string;unit_resolution_source:string;revision_lineage_source:string|null};trace_events:TraceEvent[];items:PackageItem[];documents:Array<{id:number;document_type:string;display_name:string;original_filename:string;mime_type:string;sha256:string;size_bytes:string}>;events:Array<{id:number;event_type:string;actor:string;reason:string;request_id:string;created_at:string}>;revision:RevisionContext|null;lineage:LineageContext|null};
type DecisionKind="accept"|"return";
type DecisionPrompt={kind:DecisionKind;reason:string;detail:PackageDetail};
type DecisionResponse={ok:boolean;package_id:number;request_id:string;data:PackageRow&{returned_by?:string;accepted_by?:string}};
type DecisionReceipt={kind:DecisionKind;packageId:number;packageVersionNo:number;status:string;actor:string;occurredAt:string;requestId:string;result:"SUCCESS";reason:string};
type ResubmitPrompt={detail:PackageDetail};
type SubmissionResponse={ok:boolean;package_id:number;request_id:string;data:PackageRow&{submitted_by?:string}};
type SubmissionReceipt={packageId:number;packageVersionNo:number;status:string;actor:string;occurredAt:string;requestId:string;result:"SUCCESS"};
const unitResolutionSourceLabels:Record<string,string>={ENGINEERING_CONFIRMED:"工程确认",REQUIREMENT_DECLARED:"销售需求声明"};
const traceActionLabels:Record<string,string>={CREATE:"创建交接包",SUBMIT:"提交计划部",RESUBMIT:"重新提交计划部",RETURN:"退回工程/项目部修订",ACCEPT:"计划部接收"};
const queueRoleLabels:Record<string,string>={PLANNING:"计划部待接收队列",ENGINEERING_PROJECT:"工程/项目部修订队列",COMPLETED:"已完成，无待办责任队列"};
const errorMessage=(reason:unknown)=>reason instanceof ErpApiError?`【${reason.code}】${reason.message}${reason.requestId&&!reason.message.includes(reason.requestId)?`（请求 ${reason.requestId}）`:""}`:"系统暂时无法完成请求";
const can=(user:User|null|undefined,permission:string)=>Boolean(user&&(user.permissions.includes("*")||user.permissions.includes(permission)));
function Status({value}:{value:string}){return <span className={`planning-status status-${value.toLowerCase()}`}>{statusLabel(value)}</span>}
const shanghaiTime=new Intl.DateTimeFormat("zh-CN",{timeZone:"Asia/Shanghai",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:false});
function formatShanghaiTime(value:string){return `${shanghaiTime.format(new Date(value))}（Asia/Shanghai）`}
function compactNumber(value:string){const parsed=Number(value);return Number.isFinite(parsed)?new Intl.NumberFormat("zh-CN",{maximumFractionDigits:8}).format(parsed):value}
function lossPercent(value:string){const parsed=Number(value);return Number.isFinite(parsed)?`${new Intl.NumberFormat("zh-CN",{maximumFractionDigits:6}).format(parsed*100)}%`:value}
function CopyValue({label,value}:{label:string;value:string}){return <div className="planning-copy-row"><span>{label}</span><code className="planning-trace-value">{value}</code><button type="button" className="planning-copy" onClick={()=>{if(navigator.clipboard)void navigator.clipboard.writeText(value).catch(()=>undefined)}} aria-label={`复制${label}`}>复制</button></div>}
function State({children,error=false}:{children:ReactNode;error?:boolean}){return <div className={error?"planning-state planning-error":"planning-state"} role={error?"alert":undefined}>{children}</div>}
const dialogFocusableSelector="button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),summary,[tabindex]:not([tabindex='-1'])";
function ConfirmationDialog({dialogId,title,kicker,className="",busy,confirmLabel,busyLabel="正在提交…",confirmClassName="",onCancel,onConfirm,children}:{dialogId:string;title:string;kicker:string;className?:string;busy:boolean;confirmLabel:string;busyLabel?:string;confirmClassName?:string;onCancel:()=>void;onConfirm:()=>void;children:ReactNode}){
 const dialogRef=useRef<HTMLElement|null>(null);const cancelRef=useRef<HTMLButtonElement|null>(null);const previousFocus=useRef<HTMLElement|null>(null);
 useEffect(()=>{previousFocus.current=document.activeElement instanceof HTMLElement?document.activeElement:null;const frame=window.requestAnimationFrame(()=>cancelRef.current?.focus());return()=>{window.cancelAnimationFrame(frame);previousFocus.current?.focus()}},[]);
 function onKeyDown(event:ReactKeyboardEvent<HTMLElement>){if(event.key==="Escape"){event.preventDefault();event.stopPropagation();if(!busy)onCancel();return}if(event.key!=="Tab")return;const dialog=dialogRef.current;if(!dialog)return;const focusable=Array.from(dialog.querySelectorAll<HTMLElement>(dialogFocusableSelector)).filter(node=>node.getAttribute("aria-hidden")!=="true");if(!focusable.length){event.preventDefault();dialog.focus();return}const first=focusable[0],last=focusable[focusable.length-1],active=document.activeElement;if(event.shiftKey&&(active===first||!dialog.contains(active))){event.preventDefault();last.focus()}else if(!event.shiftKey&&(active===last||!dialog.contains(active))){event.preventDefault();first.focus()}}
 return <div className="planning-dialog-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget&&!busy)onCancel()}}><section ref={dialogRef} className={`planning-dialog ${className}`.trim()} role="dialog" aria-modal="true" aria-labelledby={dialogId} aria-busy={busy} tabIndex={-1} onKeyDown={onKeyDown}><div className="planning-dialog-body"><div className="planning-dialog-heading"><div><p className="planning-kicker">{kicker}</p><h2 id={dialogId}>{title}</h2></div><button type="button" className="planning-dialog-close" aria-label="关闭确认窗口" disabled={busy} onClick={onCancel}>关闭</button></div>{children}</div><div className="planning-dialog-actions"><button ref={cancelRef} type="button" className="planning-secondary" disabled={busy} onClick={onCancel}>取消</button><button type="button" className={confirmClassName} disabled={busy} onClick={onConfirm}>{busy?busyLabel:confirmLabel}</button></div></section></div>
}
function FullPackageDigest({value}:{value:string}){return <details className="planning-confirm-digest"><summary>查看完整 Package SHA-256 摘要</summary><code>{value}</code></details>}
function FixedSnapshotConfirmation({detail}:{detail:PackageDetail}){return <section className="planning-confirm-section" aria-label="固定快照摘要"><h3>固定快照摘要</h3>{detail.items.map(item=><article className="planning-confirm-snapshot" key={item.id}><b>Product {item.product_version_code} · BOM {item.bom_version_code}</b><p>Unit Resolution v{item.unit_resolution_version_no} / {item.unit_name} · {item.unit_code}</p><ul className="planning-confirm-materials">{item.bom_lines.map(line=>{const snapshot=line.specification_snapshot;return <li key={line.id}><span>{String(snapshot.internal_material_code||`Material ID ${line.material_id}`)} · {String(snapshot.standard_name||"未保存名称")}</span><b>毛需求 {compactNumber(line.calculated_gross_quantity)} {line.unit_code}</b></li>})}</ul></article>)}<p className="planning-gate-evidence">本确认窗口内容来自不可变 v{detail.header.package_version_no} 谱系及该 Package 固定的 Product、BOM、Unit Resolution 与物料快照，不读取后来变化的 Head 或当前 BOM。</p></section>}
function RevisionConfirmation({lineage}:{lineage:LineageContext}){return <><section className="planning-confirm-section" aria-label="前驱退回"><h3>前驱退回</h3><dl className="planning-facts"><div><dt>源 Package</dt><dd>ID {lineage.previous_package_id}/v{lineage.previous_package_version_no}</dd></div><div><dt>状态</dt><dd>{statusLabel(lineage.previous_package_status)}</dd></div><div><dt>退回事件</dt><dd>{lineage.return_event_id}</dd></div><div><dt>退回操作者</dt><dd>{lineage.return_actor}</dd></div><div><dt>退回时间</dt><dd>{formatShanghaiTime(lineage.return_created_at)}</dd></div></dl><CopyValue label="退回请求号" value={lineage.return_request_id}/><div className="planning-confirm-reason"><b>完整退回原因</b><p>{lineage.return_reason}</p></div></section><section className="planning-confirm-section" aria-label="工程回复"><h3>工程回复</h3><dl className="planning-facts"><div><dt>回复</dt><dd>ID {lineage.revision_response_version_id}/v{lineage.response_version_no}</dd></div><div><dt>回复操作者</dt><dd>{lineage.response_created_by}</dd></div><div><dt>回复时间</dt><dd>{formatShanghaiTime(lineage.response_created_at)}</dd></div></dl><CopyValue label="回复请求号" value={lineage.response_request_id}/><div className="planning-response-body"><b>完整回复正文</b><p>{lineage.response_text}</p></div></section></>}
function Shell({title,subtitle,user,children}:{title:string;subtitle:string;user:User;children:ReactNode}){return <main className="planning-shell"><div className="planning-banner">并行验收环境 · 只交接产品/BOM/零件规格，不计算缺料，不创建采购或生产单据</div><header className="planning-header"><div><Link href="/" className="planning-back">← 经营工作台</Link><p className="planning-kicker">项目到计划</p><h1>{title}</h1><p>{subtitle}</p></div><div className="planning-user"><b>{user.display_name||user.username}</b><span>{roleLabel(user.role,"受控业务人员")}</span></div></header>{children}</main>}
function useSessionMutation(session:Session|null){const operations=useRef(createSessionWriteRegistry());useEffect(()=>{operations.current.clear()},[session?.csrf_token,session?.user?.username]);useEffect(()=>{const clear=()=>operations.current.clear();window.addEventListener("pagehide",clear);window.addEventListener("cyd-erp-auth-required",clear);return()=>{clear();window.removeEventListener("pagehide",clear);window.removeEventListener("cyd-erp-auth-required",clear)}},[]);return useCallback((path:string,body:Record<string,unknown>)=>{if(!session?.authenticated)throw new ErpApiError("当前会话已失效，请重新登录",{code:"SESSION_REQUIRED"});return sessionPost(operations.current,path,body,session.csrf_token||"")},[session?.authenticated,session?.csrf_token,session?.user?.username])}
function useSessionBoundaryReload(load:()=>Promise<void>){useEffect(()=>{const revalidate=()=>void load();const restore=(event:PageTransitionEvent)=>{if(isHistorySessionRestore(event))revalidate()};window.addEventListener("cyd-erp-auth-required",revalidate);window.addEventListener("pageshow",restore);return()=>{window.removeEventListener("cyd-erp-auth-required",revalidate);window.removeEventListener("pageshow",restore)}},[load])}

export function EngineeringPlanningWorkspace({projectId}:{projectId:number}){
 const[session,setSession]=useState<Session|null>(null);const[data,setData]=useState<ResolutionData|null>(null);const[packages,setPackages]=useState<PackageRow[]>([]);const[detail,setDetail]=useState<PackageDetail|null>(null);const[choices,setChoices]=useState<Record<number,number>>({});const[unitChoices,setUnitChoices]=useState<Record<number,number>>({});const[resubmitPrompt,setResubmitPrompt]=useState<ResubmitPrompt|null>(null);const[submissionReceipt,setSubmissionReceipt]=useState<SubmissionReceipt|null>(null);const[busy,setBusy]=useState(false);const[notice,setNotice]=useState("");const[error,setError]=useState("");const resubmitInFlight=useRef(false);
 const detailId=detail?.header.id;const load=useCallback(async()=>{setError("");try{const current=await api<Session>("/api/session");setSession(current);if(!current.authenticated||!can(current.user,"planning.read"))return;const [resolutionResult,packageResult]=await Promise.all([api<{data:ResolutionData}>(`/api/projects/${projectId}/requirement-resolutions`),api<{data:PackageRow[]}>(`/api/projects/${projectId}/planning-packages`)]);setData(resolutionResult.data);setPackages(packageResult.data);const selected:Record<number,number>={};const selectedUnits:Record<number,number>={};const enabledUnitIds=new Set(resolutionResult.data.enabled_units.map(unit=>Number(unit.id)));const validCandidates=new Map(resolutionResult.data.candidates.map(candidate=>[Number(candidate.bom_version_id),candidate]));for(const row of resolutionResult.data.rows){const candidate=validCandidates.get(Number(row.bom_version_id||0));if(candidate&&Number(candidate.product_id)===Number(row.product_id)&&Number(candidate.product_version_id)===Number(row.product_version_id)&&Number(candidate.bom_header_id)===Number(row.bom_header_id))selected[row.requirement_item_id]=Number(row.bom_version_id);if(row.resolved_unit_id&&enabledUnitIds.has(Number(row.resolved_unit_id)))selectedUnits[row.requirement_item_id]=Number(row.resolved_unit_id)}setChoices(selected);setUnitChoices(selectedUnits);if(detailId)setDetail((await api<{data:PackageDetail}>(`/api/planning-packages/${detailId}`)).data);}catch(reason){setError(errorMessage(reason));}},[projectId,detailId]);
 useEffect(()=>{const timer=window.setTimeout(()=>void load(),0);return()=>window.clearTimeout(timer);},[load]);
 useEffect(()=>{if(detail||!packages.length)return;const requested=Number(new URLSearchParams(window.location.search).get("package")||0);const target=packages.find(row=>Number(row.id)===requested)||(packages[0]?.status==="RETURNED"?packages[0]:null);if(target)void selectPackage(Number(target.id));},[packages,detail]);
 const mutate=useSessionMutation(session);useSessionBoundaryReload(load);
 const byBom=useMemo(()=>new Map((data?.candidates||[]).map(row=>[Number(row.bom_version_id),row])),[data?.candidates]);
 async function write(path:string,body:Record<string,unknown>,success:string){if(!session)return;if(path===`/api/planning-packages/${detail?.header.id}/submit`&&detail?.header.status==="DRAFT"&&detail.header.package_version_no>1){requestResubmit(detail);return}setBusy(true);setError("");setNotice("");try{await mutate(path,body);setNotice(success);setDetail(null);await load();}catch(reason){setError(errorMessage(reason));}finally{setBusy(false)}}
 async function saveResolutions(){if(!data)return;const rows=data.rows.flatMap(row=>{const candidate=byBom.get(choices[row.requirement_item_id]);return candidate?[{requirement_item_id:row.requirement_item_id,product_id:candidate.product_id,product_version_id:candidate.product_version_id,bom_header_id:candidate.bom_header_id,bom_version_id:candidate.bom_version_id}]:[]});if(rows.length!==data.rows.length){setError("请先为每一行选择已发布的 Product / BOM，再保存产品与 BOM 解析。");return}await write(`/api/projects/${projectId}/requirement-resolutions`,{expected_version:data.project.version,resolutions:rows},"Product / BOM 解析已保存");}
 async function saveUnitResolution(row:Resolution){const unitId=unitChoices[row.requirement_item_id];if(!unitId){setError(`需求第 ${row.line_no} 行尚未选择单位，请先选择有效单位。`);return}await write(`/api/projects/${projectId}/requirement-unit-resolutions`,{requirement_item_id:row.requirement_item_id,unit_id:unitId,expected_head_version:Number(row.unit_resolution_head_version||0)},`需求第 ${row.line_no} 行的单位解析已保存`);}
 async function selectPackage(id:number){setError("");setResubmitPrompt(null);setSubmissionReceipt(null);try{setDetail((await api<{data:PackageDetail}>(`/api/planning-packages/${id}`)).data);}catch(reason){setError(errorMessage(reason));}}
 function requestResubmit(target:PackageDetail){if(!session?.user||!can(session.user,"planning.prepare")||target.header.status!=="DRAFT"||target.header.package_version_no<=1||!target.lineage){setError("只有获准工程人员可对具备完整谱系的草稿修订包发起重新提交确认。");return}setError("");setNotice("");setResubmitPrompt({detail:target})}
 async function confirmResubmit(){if(!session||!resubmitPrompt||resubmitInFlight.current)return;const target=resubmitPrompt.detail;resubmitInFlight.current=true;setBusy(true);setError("");setNotice("");try{const result=await mutate(`/api/planning-packages/${target.header.id}/submit`,{expected_version:target.header.version}) as SubmissionResponse;const row=result.data;setSubmissionReceipt({packageId:Number(row.id||target.header.id),packageVersionNo:Number(row.package_version_no||target.header.package_version_no),status:String(row.status||"SUBMITTED"),actor:row.submitted_by||"",occurredAt:row.submitted_at||row.updated_at||"",requestId:result.request_id,result:"SUCCESS"});setResubmitPrompt(null);setNotice("修订包已重新提交");await load()}catch(reason){setResubmitPrompt(null);setError(errorMessage(reason))}finally{resubmitInFlight.current=false;setBusy(false)}}
 if(!session)return <State error={Boolean(error)}>{error||"正在读取会话…"}</State>;if(!session.authenticated)return <State>请先从经营工作台登录。</State>;if(!can(session.user,"planning.prepare"))return <State error>此页面仅供项目负责人或获准管理人员使用。</State>;if(!data)return <State error={Boolean(error)}>{error||"正在读取项目与解析…"}</State>;
 const unitById=new Map(data.enabled_units.map(unit=>[Number(unit.id),unit]));
 const unitComplete=(row:Resolution)=>Boolean(row.unit_resolution_id&&row.unit_resolution_version_no&&row.resolved_unit_id&&unitById.has(Number(row.resolved_unit_id)));
 const productBomComplete=(row:Resolution)=>{const candidate=byBom.get(Number(row.bom_version_id||0));return Boolean(row.product_id&&row.product_version_id&&row.bom_header_id&&row.bom_version_id&&candidate&&Number(candidate.product_id)===Number(row.product_id)&&Number(candidate.product_version_id)===Number(row.product_version_id)&&Number(candidate.bom_header_id)===Number(row.bom_header_id));};
 const unitChoiceDirty=(row:Resolution)=>Number(unitChoices[row.requirement_item_id]||0)!==Number(row.resolved_unit_id||0);
 const productChoiceDirty=(row:Resolution)=>Number(choices[row.requirement_item_id]||0)!==Number(row.bom_version_id||0);
 const missing=data.rows.flatMap(row=>{const fields:string[]=[];if(!row.unit_resolution_id||!row.resolved_unit_id)fields.push("单位");else if(!unitById.has(Number(row.resolved_unit_id)))fields.push("单位（当前解析引用的单位已停用，需重新确认）");else if(unitChoiceDirty(row))fields.push("单位（当前选择尚未保存）");if(!row.product_version_id||!row.bom_version_id)fields.push("Product / BOM");else if(!productBomComplete(row))fields.push("Product / BOM（当前解析已失效，需重新选择并保存）");else if(productChoiceDirty(row))fields.push("Product / BOM（当前选择尚未保存）");return fields.length?[`第 ${row.line_no} 行「${row.provisional_name}」：${fields.join("、")}`]:[]});
 const allPersistedResolutionsComplete=data.rows.length>0&&data.rows.every(row=>unitComplete(row)&&productBomComplete(row)&&!unitChoiceDirty(row)&&!productChoiceDirty(row));
 const allProductChoicesSelected=data.rows.length>0&&data.rows.every(row=>Boolean(byBom.get(choices[row.requirement_item_id])));
 const latest=packages[0];const canCreate=!latest;
 if(detail&&(resubmitPrompt||submissionReceipt))return <Shell title={`${data.project.project_code} · 计划交接`} subtitle="修订包重新提交必须先核对固定谱系与后果。" user={session.user!}><section className="planning-panel">{submissionReceipt?<SubmissionReceiptView receipt={submissionReceipt} onOpen={()=>setSubmissionReceipt(null)}/>:<PackageView detail={detail} session={session}/>} {notice?<State>{notice}</State>:null}{error?<State error>{error}</State>:null}</section>{resubmitPrompt?<ResubmitDialog prompt={resubmitPrompt} busy={busy} onCancel={()=>setResubmitPrompt(null)} onConfirm={()=>void confirmResubmit()}/>:null}</Shell>;
 if(!detail&&packages.length)return <Shell title={`${data.project.project_code} · 计划交接`} subtitle="已有 Package 后仅可查看不可变版本；Planning 退回时须在源 v1 详情保存工程修订回复。" user={session.user!}><div className="planning-grid"><aside className="planning-panel"><div className="planning-title"><div><p className="planning-kicker">交接包历史</p><h2>交接包版本</h2></div><span className="planning-count">{packages.length}</span></div><div className="planning-list">{packages.map(row=><button key={row.id} className="planning-row" onClick={()=>void selectPackage(row.id)}><span><b>交接包 v{row.package_version_no}</b><small>{row.package_digest.slice(0,12)}…</small></span><Status value={row.status}/><strong>{row.item_count} 项需求</strong>{row.return_reason?<small>{row.return_reason}</small>:null}</button>)}</div></aside><section className="planning-panel"><State>请选择左侧 Package；退回后的 Product/BOM、Unit Resolution 和物料快照均只读，当前流程不会显示解析选择器。</State>{notice?<State>{notice}</State>:null}{error?<State error>{error}</State>:null}</section></div></Shell>;
 return <Shell title={`${data.project.project_code} · 计划交接`} subtitle="逐项确认工程单位并锁定已发布 Product/BOM，预览零件规格快照后提交计划部门。" user={session.user!}><div className="planning-grid"><aside className="planning-panel"><div className="planning-title"><div><p className="planning-kicker">交接包历史</p><h2>交接包版本</h2></div><span className="planning-count">{packages.length}</span></div><div className="planning-list">{packages.length?packages.map(row=><button key={row.id} className={`planning-row ${detail?.header.id===row.id?"active":""}`} onClick={()=>void selectPackage(row.id)}><span><b>交接包 v{row.package_version_no}</b><small>{row.package_digest.slice(0,12)}…</small></span><Status value={row.status}/><strong>{row.item_count} 项需求</strong>{row.return_reason?<small>{row.return_reason}</small>:null}</button>):<State>尚未生成计划交接包。</State>}</div></aside><section className="planning-panel">{detail?<PackageView key={`${detail.header.id}:${detail.header.status}:${detail.header.revision_response_version_id||0}`} detail={detail} session={session}/>:<><div className="planning-title"><div><p className="planning-kicker">需求解析</p><h2>需求明细解析</h2></div><span>{data.project.project_owner}</span></div><div className="planning-unit-notice">工程单位确认只写入追加式解析版本，不会改写销售原始需求，也不会从 BOM 推断单位。</div>{data.rows.map(row=>{const resolvedUnit=row.resolved_unit_id?unitById.get(Number(row.resolved_unit_id)):undefined;const unitIsComplete=unitComplete(row);const productIsComplete=productBomComplete(row);const selectedUnit=unitChoices[row.requirement_item_id];const selectedCandidate=choices[row.requirement_item_id];return <div className="planning-card planning-resolution" key={row.requirement_item_id}><div className="planning-resolution-summary"><b>{row.line_no}. {row.provisional_name}</b><p>需求数量：{row.quantity} · 销售原始单位：{row.unit_pending?"待确认":row.unit_code||"已声明"}</p><small>{row.specification_requirement||"未填写规格要求"}</small><div className="planning-resolution-statuses"><span className={unitIsComplete?"planning-resolution-state complete":"planning-resolution-state missing"}>单位：{unitIsComplete?"已完成":"未完成"}</span><span className={productIsComplete?"planning-resolution-state complete":"planning-resolution-state missing"}>Product / BOM：{productIsComplete?"已完成":"未完成"}</span></div>{row.unit_resolution_id?<p className={unitIsComplete?"planning-resolution-version":"planning-resolution-version warning"}>{row.resolved_unit_name||"历史单位"} · {row.resolved_unit_code||`ID ${row.resolved_unit_id}`} · Unit Resolution v{row.unit_resolution_version_no}（Head v{row.unit_resolution_head_version}） · 来源：{unitResolutionSourceLabels[row.unit_resolution_source_type||""]||"可追溯历史来源"}{resolvedUnit?"":" · 当前已停用，生成新交接包前须重新确认"}</p>:<p className="planning-resolution-version warning">尚无已持久化的 Unit Resolution</p>}</div><div className="planning-resolution-controls"><div className="planning-field"><label htmlFor={`unit-resolution-${row.requirement_item_id}`}>工程单位解析</label><select id={`unit-resolution-${row.requirement_item_id}`} aria-label={`需求 ${row.line_no} 单位`} value={selectedUnit||""} onChange={event=>{const unitId=Number(event.target.value);setUnitChoices(value=>{const next={...value};if(unitId)next[row.requirement_item_id]=unitId;else delete next[row.requirement_item_id];return next})}}><option value="">请选择有效单位</option>{data.enabled_units.map(unit=><option key={unit.id} value={unit.id}>{unit.name} · {unit.code}</option>)}</select><small>使用稳定 Unit ID；不会写回销售需求。</small><button type="button" disabled={busy||!selectedUnit||Number(row.resolved_unit_id)===selectedUnit} onClick={()=>void saveUnitResolution(row)}>保存单位确认</button></div><div className="planning-field"><label htmlFor={`product-bom-${row.requirement_item_id}`}>Product / BOM 解析</label><select id={`product-bom-${row.requirement_item_id}`} aria-label={`需求 ${row.line_no} Product BOM`} value={selectedCandidate||""} onChange={event=>{const bomVersionId=Number(event.target.value);setChoices(value=>{const next={...value};if(bomVersionId)next[row.requirement_item_id]=bomVersionId;else delete next[row.requirement_item_id];return next})}}><option value="">请选择已发布 Product / BOM</option>{data.candidates.map(candidate=><option key={candidate.bom_version_id} value={candidate.bom_version_id}>{candidate.product_code} / {candidate.product_version_code} · {candidate.bom_code} / {candidate.bom_version_code} · {candidate.bom_line_count} 行</option>)}</select><small>{productIsComplete?"已持久化；修改选择后需再次保存。":"本地选择尚未保存时不会计入交接完整性。"}</small></div></div></div>})}<div id="planning-resolution-missing" className={missing.length?"planning-missing":"planning-missing complete"} aria-live="polite">{missing.length?<><b>生成交接包前仍需完成：</b><ul>{missing.map(item=><li key={item}>{item}</li>)}</ul></>:<b>所有需求行的单位与 Product / BOM 均已持久化完成。</b>}</div><div className="planning-actions"><button disabled={busy||!allProductChoicesSelected} onClick={()=>void saveResolutions()}>保存 Product / BOM 解析</button>{canCreate?<button disabled={busy||!allPersistedResolutionsComplete} aria-describedby="planning-resolution-missing" className="planning-secondary" onClick={()=>void write(`/api/projects/${projectId}/planning-packages`,{expected_version:data.project.version},"不可变交接包已生成")}>生成交接包 v{packages.length+1}</button>:null}</div></>}{detail?.header.status==="DRAFT"?<div className="planning-actions"><button disabled={busy} onClick={()=>void write(`/api/planning-packages/${detail.header.id}/submit`,{expected_version:detail.header.version},detail.header.package_version_no>1?"修订包已重新提交":"交接包已提交计划部")}>{detail.header.package_version_no>1?"重新提交计划部":"提交计划部"}</button></div>:null}{notice?<State>{notice}</State>:null}{error?<State error>{error}</State>:null}</section></div></Shell>;
}

export function PlanningHandoffWorkspace(){
 const[session,setSession]=useState<Session|null>(null);const[pending,setPending]=useState<PackageRow[]>([]);const[processed,setProcessed]=useState<PackageRow[]>([]);const[view,setView]=useState<"PENDING"|"PROCESSED">("PENDING");const[detail,setDetail]=useState<PackageDetail|null>(null);const[decisionPrompt,setDecisionPrompt]=useState<DecisionPrompt|null>(null);const[receipt,setReceipt]=useState<DecisionReceipt|null>(null);const[busy,setBusy]=useState(false);const[notice,setNotice]=useState("");const[error,setError]=useState("");const decisionInFlight=useRef(false);
 const load=useCallback(async()=>{setError("");try{const current=await api<Session>("/api/session");setSession(current);if(!current.authenticated||!can(current.user,"planning.read"))return;const [queue,history]=await Promise.all([api<{data:PackageRow[]}>("/api/planning-handoffs?status=SUBMITTED&page_size=100"),api<{data:PackageRow[]}>("/api/planning-handoffs?status=PROCESSED&page_size=100")]);setPending(queue.data);setProcessed(history.data);}catch(reason){setError(errorMessage(reason));}},[]);useEffect(()=>{const timer=window.setTimeout(()=>void load(),0);return()=>window.clearTimeout(timer);},[load]);
 const mutate=useSessionMutation(session);useSessionBoundaryReload(load);
 async function choose(id:number){setError("");setReceipt(null);setDecisionPrompt(null);try{setDetail((await api<{data:PackageDetail}>(`/api/planning-packages/${id}`)).data);}catch(reason){setError(errorMessage(reason));}}
 function requestDecision(kind:DecisionKind,reason=""){const normalizedReason=reason.trim();if(!detail||detail.header.status!=="SUBMITTED"||!session?.user||!can(session.user,"planning.accept")){setError("只有获准计划人员可对当前已提交交接包打开决策确认。");return}if(kind==="return"&&!normalizedReason){setError("请填写退回原因后再确认。");return}setError("");setNotice("");setDecisionPrompt({kind,reason:normalizedReason,detail});}
 async function confirmDecision(){if(!session||!decisionPrompt||decisionInFlight.current)return;const prompt=decisionPrompt;const currentDetail=prompt.detail;decisionInFlight.current=true;setBusy(true);setError("");setNotice("");try{const result=await mutate(`/api/planning-packages/${currentDetail.header.id}/${prompt.kind}`,{expected_version:currentDetail.header.version,...(prompt.kind==="return"?{reason:prompt.reason}:{})}) as DecisionResponse;const row=result.data;setReceipt({kind:prompt.kind,packageId:Number(row.id||currentDetail.header.id),packageVersionNo:Number(row.package_version_no||currentDetail.header.package_version_no),status:String(row.status|| (prompt.kind==="accept"?"ACCEPTED":"RETURNED")),actor:prompt.kind==="return"?row.returned_by||"":row.accepted_by||"",occurredAt:prompt.kind==="return"?row.returned_at||row.updated_at||"":row.accepted_at||row.updated_at||"",requestId:result.request_id,result:"SUCCESS",reason:prompt.kind==="return"?String(row.return_reason??""):""});setDecisionPrompt(null);setDetail(null);setView("PROCESSED");setNotice(prompt.kind==="accept"?"计划交接包已接收；未自动执行下一业务阶段":"已退回工程/项目部修订；旧包保持不可变");await load();}catch(cause){setDecisionPrompt(null);setError(errorMessage(cause));}finally{decisionInFlight.current=false;setBusy(false)}}
 function returnPackage(event:FormEvent<HTMLFormElement>){event.preventDefault();requestDecision("return",String(new FormData(event.currentTarget).get("reason")||""))}
 async function openReceiptDetail(){if(!receipt)return;setView("PROCESSED");await choose(receipt.packageId)}
 if(!session)return <State error={Boolean(error)}>{error||"正在读取会话…"}</State>;if(!session.authenticated)return <State>请先从经营工作台登录。</State>;if(!can(session.user,"planning.read"))return <State error>没有权限读取计划交接。</State>;
 const rows=view==="PENDING"?pending:processed;
 return <Shell title="计划部门交接工作台" subtitle="只读核对项目、产品、BOM 与零件规格；接收或填写原因退回。" user={session.user!}>
  <div className="planning-grid">
   <aside className="planning-panel">
    <div className="planning-title"><div><p className="planning-kicker">决策队列</p><h2>{view==="PENDING"?"待接收交接包":"已处理交接包"}</h2></div><span className="planning-count">{rows.length}</span></div>
    <div className="planning-view-tabs" role="tablist" aria-label="计划交接视图">
     <button type="button" role="tab" aria-selected={view==="PENDING"} className={view==="PENDING"?"active":""} onClick={()=>{setView("PENDING");setDetail(null);setReceipt(null);setDecisionPrompt(null)}}>待接收 <span>{pending.length}</span></button>
     <button type="button" role="tab" aria-selected={view==="PROCESSED"} className={view==="PROCESSED"?"active":""} onClick={()=>{setView("PROCESSED");setDetail(null);setReceipt(null);setDecisionPrompt(null)}}>已处理 <span>{processed.length}</span></button>
    </div>
    <div className="planning-list" role="tabpanel">
     {rows.length?rows.map(row=><button key={row.id} type="button" className={`planning-row ${detail?.header.id===row.id?"active":""}`} onClick={()=>void choose(row.id)}><span><b>{row.project_code} · Package ID {row.id}/v{row.package_version_no}</b><small>{row.customer_name}</small></span><Status value={row.status}/><strong>{row.project_name}</strong>{row.return_reason?<small className="planning-row-reason">{row.return_reason}</small>:null}</button>):<State>{view==="PENDING"?"当前没有待接收交接包。":"当前没有已处理交接包。"}</State>}
    </div>
   </aside>
   <section className="planning-panel">
    {detail?<><PackageView key={`${detail.header.id}:${detail.header.status}:${detail.header.revision_response_version_id||0}`} detail={detail} session={session}/>{detail.header.status==="SUBMITTED"&&can(session.user,"planning.accept")?<div className="planning-actions planning-decision-actions"><button disabled={busy} onClick={()=>requestDecision("accept")}>接收交接包</button><form className="planning-form" onSubmit={returnPackage}><label>退回原因（必填）<textarea name="reason" required maxLength={1000} placeholder="说明需工程/项目部修订的产品、BOM 或规格问题"/></label><button className="planning-danger" disabled={busy}>退回工程/项目部修订</button></form></div>:detail.header.status==="SUBMITTED"?<State>当前账号仅可查看，没有接收或退回权限。</State>:null}</>:receipt?<DecisionReceiptView receipt={receipt} onOpen={()=>void openReceiptDetail()}/>:<State>从左侧选择交接包查看不可变快照。</State>}
    {notice?<State>{notice}</State>:null}{error?<State error>{error}</State>:null}
   </section>
  </div>
  {decisionPrompt?<DecisionDialog prompt={decisionPrompt} busy={busy} onCancel={()=>setDecisionPrompt(null)} onConfirm={()=>void confirmDecision()}/>:null}
 </Shell>;
}

function DecisionDialog({prompt,busy,onCancel,onConfirm}:{prompt:DecisionPrompt;busy:boolean;onCancel:()=>void;onConfirm:()=>void}){
 const returning=prompt.kind==="return";const detail=prompt.detail;const lineage=detail.lineage;
 if(returning)return <ConfirmationDialog dialogId="planning-return-title" title="确认退回工程/项目部修订" kicker="决策确认" busy={busy} confirmLabel="确认退回" confirmClassName="planning-danger" onCancel={onCancel} onConfirm={onConfirm}><section className="planning-confirm-section"><h3>当前目标</h3><dl className="planning-facts"><div><dt>项目</dt><dd>{detail.header.project_code}</dd></div><div><dt>Package</dt><dd>ID {detail.header.id}/v{detail.header.package_version_no}</dd></div><div><dt>当前状态</dt><dd>{statusLabel(detail.header.status)}</dd></div></dl><FullPackageDigest value={detail.header.package_digest}/></section><section className="planning-confirm-section"><h3>退回后果</h3><div className="planning-confirm-reason"><b>将按以下完整原因退回</b><p>{prompt.reason}</p></div><ul className="planning-consequence-list"><li>写入一条不可变退回事件。</li><li>当前交接包转为已退回，责任队列转回工程/项目部。</li><li>当前版本不再允许接收或重复退回。</li><li>不自动创建任何下游业务单据。</li></ul></section></ConfirmationDialog>;
 return <ConfirmationDialog dialogId="planning-accept-title" title={`确认最终接收 Package v${detail.header.package_version_no}`} kicker="最终接收确认" className="planning-handoff-dialog" busy={busy} confirmLabel="确认最终接收" onCancel={onCancel} onConfirm={onConfirm}><section className="planning-confirm-section" aria-label="当前目标"><h3>当前目标</h3><dl className="planning-facts"><div><dt>项目</dt><dd>{detail.header.project_code}</dd></div><div><dt>Package</dt><dd>ID {detail.header.id}/v{detail.header.package_version_no}</dd></div><div><dt>当前状态</dt><dd>{statusLabel(detail.header.status)}</dd></div><div><dt>提交人</dt><dd>{detail.header.submitted_by||"未记录"}</dd></div><div><dt>{detail.header.package_version_no>1?"重新提交时间":"提交时间"}</dt><dd>{detail.header.submitted_at?formatShanghaiTime(detail.header.submitted_at):"未记录"}</dd></div></dl><FullPackageDigest value={detail.header.package_digest}/></section>{lineage?<RevisionConfirmation lineage={lineage}/>:<State error>当前 Package 缺少固定修订谱系，不能确认最终接收。</State>}<FixedSnapshotConfirmation detail={detail}/><section className="planning-confirm-section" aria-label="接收后果"><h3>接收后果</h3><ul className="planning-consequence-list"><li>写入一条不可变接收事件。</li><li>Package ID {detail.header.id}/v{detail.header.package_version_no} 转为已接收。</li>{lineage?<li>Package ID {lineage.previous_package_id}/v{lineage.previous_package_version_no} 继续保持已退回。</li>:null}<li>当前版本不再允许退回或重复接收。</li><li>不自动创建采购申请、工单、库存或财务记录。</li></ul></section><section className="planning-confirm-section planning-next-stage" aria-label="下一业务阶段"><h3>下一业务阶段</h3><p><b>下一业务阶段：计划部门基于已接收的Package v{detail.header.package_version_no}进行物料需求计算和缺料分析，随后通过独立操作形成采购需求交接。</b></p><ul><li>当前未指定具体处理人。</li><li>当前未配置处理时限。</li><li>接收本身不会自动执行下一阶段。</li></ul></section></ConfirmationDialog>
}

function DecisionReceiptView({receipt,onOpen}:{receipt:DecisionReceipt;onOpen:()=>void}){
 const returning=receipt.kind==="return";
 return <div className="planning-receipt" role="status"><p className="planning-kicker">决策凭证</p><h2>操作完成凭证</h2><dl className="planning-facts"><div><dt>操作</dt><dd>{returning?"退回工程/项目部修订":"接收交接包"}</dd></div><div><dt>Package</dt><dd>ID {receipt.packageId}/v{receipt.packageVersionNo}</dd></div><div><dt>状态</dt><dd>{statusLabel(receipt.status)}</dd></div><div><dt>操作者</dt><dd>{receipt.actor||"服务端未返回操作者"}</dd></div><div><dt>时间</dt><dd>{receipt.occurredAt?formatShanghaiTime(receipt.occurredAt):"服务端未返回操作时间"}</dd></div><div><dt>结果</dt><dd>{statusLabel(receipt.result)}</dd></div></dl><CopyValue label="请求号" value={receipt.requestId}/>{returning?<div className="planning-confirm-reason"><b>数据库保存的退回原因</b><p>{receipt.reason}</p></div>:null}<p>{returning?"下一队列：工程/项目部修订队列；具体接收人未指定；处理时限未配置。":`下一队列：计划部物料需求计算与缺料分析（须基于已接收的 Package v${receipt.packageVersionNo} 通过独立操作启动）；当前未指定具体处理人；当前未配置处理时限。`}</p><button type="button" onClick={onOpen}>查看已处理详情</button></div>
}

function ResubmitDialog({prompt,busy,onCancel,onConfirm}:{prompt:ResubmitPrompt;busy:boolean;onCancel:()=>void;onConfirm:()=>void}){
 const detail=prompt.detail;const lineage=detail.lineage;
 return <ConfirmationDialog dialogId="planning-resubmit-title" title={`确认重新提交 Package v${detail.header.package_version_no}`} kicker="重新提交确认" className="planning-resubmit-dialog" busy={busy} confirmLabel="确认重新提交" onCancel={onCancel} onConfirm={onConfirm}><section className="planning-confirm-section" aria-label="重新提交目标"><h3>当前目标</h3><dl className="planning-facts"><div><dt>项目</dt><dd>{detail.header.project_code}</dd></div><div><dt>目标 Package</dt><dd>ID {detail.header.id}/v{detail.header.package_version_no}</dd></div><div><dt>当前状态</dt><dd>{statusLabel(detail.header.status)}</dd></div></dl><FullPackageDigest value={detail.header.package_digest}/></section>{lineage?<RevisionConfirmation lineage={lineage}/>:<State error>当前草稿交接包缺少固定修订谱系，不能重新提交。</State>}<FixedSnapshotConfirmation detail={detail}/><section className="planning-confirm-section" aria-label="重新提交后果"><h3>提交后果</h3><ul className="planning-consequence-list"><li>写入一条不可变重新提交事件。</li><li>目标 Package ID {detail.header.id}/v{detail.header.package_version_no} 转为已提交。</li><li>提交后进入计划部待接收队列。</li><li>不自动创建采购申请、工单、库存或财务等下游业务记录。</li></ul></section></ConfirmationDialog>
}

function SubmissionReceiptView({receipt,onOpen}:{receipt:SubmissionReceipt;onOpen:()=>void}){
 return <div className="planning-receipt" role="status"><p className="planning-kicker">重新提交凭证</p><h2>重新提交完成凭证</h2><dl className="planning-facts"><div><dt>操作</dt><dd>重新提交计划部</dd></div><div><dt>Package</dt><dd>ID {receipt.packageId}/v{receipt.packageVersionNo}</dd></div><div><dt>状态</dt><dd>{statusLabel(receipt.status)}</dd></div><div><dt>操作者</dt><dd>{receipt.actor||"服务端未返回操作者"}</dd></div><div><dt>时间</dt><dd>{receipt.occurredAt?formatShanghaiTime(receipt.occurredAt):"服务端未返回操作时间"}</dd></div><div><dt>结果</dt><dd>{statusLabel(receipt.result)}</dd></div></dl><CopyValue label="请求号" value={receipt.requestId}/><p>下一队列：计划部待接收队列；当前未指定具体处理人；当前未配置处理时限；本次重新提交未自动创建任何下游单据。</p><button type="button" onClick={onOpen}>查看已提交详情</button></div>
}

function PackageView({detail,session}:{detail:PackageDetail;session:Session}){
 const terminal=detail.header.status==="RETURNED"||detail.header.status==="ACCEPTED";
 return <>
  <div className="planning-title"><div><p className="planning-kicker">不可变快照</p><h2>{detail.header.project_code} · 交接包 v{detail.header.package_version_no}</h2></div><Status value={detail.header.status}/></div>
  {!detail.traceability.complete?<State error>该交接包的创建请求号追溯不完整；页面没有补写或猜测历史数据。</State>:null}
  {detail.header.return_reason?<div className="planning-return"><b>计划部退回原因</b><p>{detail.header.return_reason}</p></div>:null}
  <dl className="planning-facts planning-package-facts">
   <div><dt>Package 稳定 ID</dt><dd>{detail.header.id}</dd></div>
   <div><dt>Package Version</dt><dd>v{detail.header.package_version_no}</dd></div>
   <div><dt>当前状态</dt><dd>{statusLabel(detail.header.status)}</dd></div>
   <div><dt>当前责任角色队列</dt><dd>{queueRoleLabels[detail.responsibility.queue_role]||detail.responsibility.queue_role}</dd></div>
   <div><dt>具体接收人</dt><dd>{detail.responsibility.assignee||"未指定具体接收人"}</dd></div>
   <div><dt>处理时限</dt><dd>{detail.responsibility.handling_deadline||"未配置处理时限"}</dd></div>
   <div><dt>客户</dt><dd>{detail.header.customer_code} · {detail.header.customer_name}</dd></div>
   <div><dt>项目负责人</dt><dd>{detail.header.project_owner}</dd></div>
  </dl>
  <div className="planning-card planning-trace-card"><h3>Package 完整摘要</h3><CopyValue label="SHA-256" value={detail.header.package_digest}/></div>
  <div className="planning-card"><h3>客户需求摘要</h3><p>{detail.header.customer_requirement_summary}</p></div>
  <div className="planning-card"><h3>事件时间线</h3><p className="planning-evidence-note">仅展示当前 Package 的不可变事件及其精确关联的创建审计；所有时间统一为 Asia/Shanghai。</p><div className="planning-history">{detail.trace_events.map(event=><article className="planning-event" key={event.id}><div className="planning-event-heading"><div><code className="planning-event-code">{event.action}</code><b>{traceActionLabels[event.action]||event.action}</b></div><span className={event.result==="SUCCESS"?"planning-event-result success":"planning-event-result warning"}>{statusLabel(event.result)}</span></div><dl><div><dt>操作者</dt><dd>{event.actor}</dd></div><div><dt>时间</dt><dd>{formatShanghaiTime(event.occurred_at)}</dd></div><div><dt>结果</dt><dd>{event.result==="SUCCESS"?`成功 · ${event.evidence_source==="PACKAGE_EVENT"?"不可变事件已提交":"创建审计与快照匹配"}`:"追溯不完整 · 缺少权威请求号"}</dd></div><div><dt>证据来源</dt><dd>{event.evidence_source==="PACKAGE_EVENT"?"Package Event":"Package Snapshot + Package 范围创建审计"}</dd></div></dl>{event.request_id?<CopyValue label="请求号" value={event.request_id}/>:<p className="planning-warning">请求号未持久化，未补写或伪造。</p>}{event.reason?<p><b>原因：</b>{event.reason}</p>:null}</article>)}</div></div>
  {detail.items.map(item=><article className="planning-card planning-package-item" key={item.id}>
   <div className="planning-title"><div><p className="planning-kicker">需求项 {item.line_no}</p><h3>{item.provisional_name}</h3></div><strong>需求 {compactNumber(item.required_quantity)} {item.unit_code}</strong></div>
   <div className="planning-evidence-grid">
    <section className="planning-evidence"><h4>Product</h4><dl><div><dt>Product 稳定 ID</dt><dd>{item.product_id}</dd></div><div><dt>编码</dt><dd>{item.product_code}</dd></div><div><dt>Product Version 稳定 ID</dt><dd>{item.product_version_id}</dd></div><div><dt>Version</dt><dd>{item.product_version_code}</dd></div><div><dt>当前 Product 状态</dt><dd><Status value={item.product_current_status}/></dd></div><div><dt>当前 Product Version 状态</dt><dd><Status value={item.product_version_current_status}/></dd></div></dl></section>
    <section className="planning-evidence"><h4>BOM</h4><dl><div><dt>BOM 稳定 ID</dt><dd>{item.bom_header_id}</dd></div><div><dt>编码</dt><dd>{item.bom_code}</dd></div><div><dt>BOM Version 稳定 ID</dt><dd>{item.bom_version_id}</dd></div><div><dt>Version</dt><dd>{item.bom_version_code}</dd></div><div><dt>当前 BOM 状态</dt><dd><Status value={item.bom_current_status}/></dd></div><div><dt>当前 BOM Version 状态</dt><dd><Status value={item.bom_version_current_status}/></dd></div></dl></section>
   </div>
   <p className="planning-gate-evidence">{detail.traceability.complete?"交接包创建时服务端已通过 Product/BOM 已生效与版本已发布门禁（非生成时状态快照）。证据来源：交接包创建服务门禁 + 成功创建追溯。":"交接包创建服务合同要求 Product/BOM 已生效且版本已发布；当前创建请求追溯不完整，页面不把当前状态冒充生成时快照。"}</p>
   <section className="planning-unit-boundary"><h4>单位边界</h4><dl><div><dt>销售原始单位</dt><dd>{item.source_unit_pending?"待确认":`${item.source_unit_name||""} · ${item.source_unit_code||""}`}</dd></div><div><dt>工程正式解析</dt><dd>{item.unit_name} · {item.unit_code}</dd></div><div><dt>Unit ID</dt><dd>{item.unit_id}</dd></div><div><dt>Unit Resolution ID</dt><dd>{item.unit_resolution_id}</dd></div><div><dt>Unit Resolution Version</dt><dd>v{item.unit_resolution_version_no}</dd></div><div><dt>Resolution 来源</dt><dd>{unitResolutionSourceLabels[item.unit_resolution_source_type]||item.unit_resolution_source_type}</dd></div></dl><p>本 Package 使用 Package Item 固定引用的 Unit Resolution v{item.unit_resolution_version_no}，不读取后来变化的 Head；单位名称和代码来自固定 Unit ID 的稳定关联对象；工程确认没有改写销售原始需求。</p></section>
   <h4>物料不可变快照</h4>
   <div className="planning-table-scroll planning-material-table" aria-label={`需求第 ${item.line_no} 行 BOM 零件规格`}><table className="planning-lines"><thead><tr><th>行</th><th>正式内部物料</th><th>追溯信息</th><th>单耗</th><th>损耗率</th><th>毛需求</th></tr></thead><tbody>{item.bom_lines.map(line=>{const snap=line.specification_snapshot;return <tr key={line.id}><td>{line.line_no}</td><td><b>{String(snap.internal_material_code||"")} · {String(snap.standard_name||"")}</b><br/><code>{String(snap.manufacturer_part_number||snap.manufacturer||snap.brand||"无附加型号")}</code></td><td>Material ID {line.material_id}</td><td>{compactNumber(line.quantity_per)} {line.unit_code}</td><td>{lossPercent(line.loss_rate)}</td><td>{compactNumber(line.calculated_gross_quantity)} {line.unit_code}</td></tr>})}</tbody></table></div>
   <div className="planning-material-cards">{item.bom_lines.map(line=>{const snap=line.specification_snapshot;return <article className="planning-material-card" key={line.id}><div><span>物料 {line.line_no}</span><b>{String(snap.internal_material_code||"")} · {String(snap.standard_name||"")}</b></div><dl><div><dt>单耗</dt><dd>{compactNumber(line.quantity_per)} {line.unit_code}</dd></div><div><dt>损耗率</dt><dd>{lossPercent(line.loss_rate)}</dd></div><div><dt>毛需求</dt><dd>{compactNumber(line.calculated_gross_quantity)} {line.unit_code}</dd></div></dl><details><summary>追溯信息 · Material ID {line.material_id}</summary><p>{String(snap.manufacturer_part_number||snap.manufacturer||snap.brand||"无附加型号")}</p></details></article>})}</div>
  </article>)}
  <div className="planning-card"><h3>受控项目资料</h3>{detail.documents.length?detail.documents.map(doc=><div className="planning-doc" key={doc.id}><b>{doc.document_type} · {doc.display_name}</b><span>{doc.original_filename} · {doc.mime_type} · {doc.size_bytes} bytes</span><small>SHA {doc.sha256.slice(0,16)}…</small></div>):<p>没有关联资料。</p>}</div>
  <div className="planning-card planning-decision-guide"><h3>操作说明</h3><p><b>接收交接包：</b>确认该不可变快照可进入后续计划工作；不会在本页自动创建缺料、采购或生产单据。</p><p><b>退回工程/项目部修订：</b>必须填写原因；旧 Package 保持不可变，工程/项目部保存修订回复后生成并重新提交固定后继版本。</p>{terminal?<p className="planning-terminal"><b>当前为{statusLabel(detail.header.status)}终态：</b>接收和退回按钮已停用并隐藏，不能再次处理该版本。</p>:null}</div>
  <RevisionResponseWorkflow detail={detail} session={session}/>
 </>
}

function RevisionResponseWorkflow({detail,session}:{detail:PackageDetail;session:Session}){
 const[revision,setRevision]=useState<RevisionContext|null>(detail.revision);const[responseText,setResponseText]=useState(detail.revision?.response_text||"");const[confirm,setConfirm]=useState(false);const[busy,setBusy]=useState(false);const[notice,setNotice]=useState("");const[error,setError]=useState("");
 const mutate=useSessionMutation(session);const editable=Boolean(session?.authenticated&&can(session.user,"planning.prepare")&&["engineering","manager","admin"].includes(session.user?.role||"")&&detail.header.status==="RETURNED"&&detail.responsibility.queue_role==="ENGINEERING_PROJECT");
 const saved=Boolean(revision?.revision_response_version_id&&revision?.response_text);const dirty=responseText!==String(revision?.response_text||"");const responseLength=[...responseText.replace(/\r\n?/g,"\n").trim()].length;
 async function refreshRevision(){const current=(await api<{data:PackageDetail}>(`/api/planning-packages/${detail.header.id}`)).data;setRevision(current.revision);setResponseText(current.revision?.response_text||"")}
 async function saveResponse(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);setNotice("");setError("");try{await mutate(`/api/planning-packages/${detail.header.id}/revision-responses`,{expected_head_version:Number(revision?.response_head_version||0),response_text:responseText});await refreshRevision();setNotice("工程修订回复草稿已保存并形成新的不可变 Version") }catch(reason){setError(errorMessage(reason))}finally{setBusy(false)}}
 async function generateSuccessor(){if(!revision?.revision_response_version_id||!revision.response_head_version)return;setBusy(true);setNotice("");setError("");try{const result=await mutate(`/api/planning-packages/${detail.header.id}/successor`,{expected_package_version:detail.header.version,expected_response_head_version:revision.response_head_version,revision_response_version_id:revision.revision_response_version_id}) as {package_id:number};const target=new URL(window.location.href);target.searchParams.set("package",String(result.package_id));window.location.assign(target.toString())}catch(reason){setConfirm(false);setError(errorMessage(reason));setBusy(false)}}
 return <>
  {detail.lineage?<RevisionLineageCard detail={detail}/>:null}
  {revision?<section className="planning-card planning-revision-readonly" aria-label="工程修订回复追溯"><div className="planning-title"><div><p className="planning-kicker">退回回复</p><h3>计划部退回与工程回复</h3></div>{revision.revision_response_version_id?<span className="planning-resolution-state complete">回复 v{revision.response_version_no}</span>:<span className="planning-resolution-state missing">等待工程回复</span>}</div><dl className="planning-facts"><div><dt>退回事件 ID</dt><dd>{revision.return_event_id}</dd></div><div><dt>退回操作者</dt><dd>{revision.return_actor}</dd></div><div><dt>退回时间</dt><dd>{formatShanghaiTime(revision.return_created_at)}</dd></div><div><dt>回复版本头</dt><dd>{revision.response_head_version?`v${revision.response_head_version}`:"尚未建立"}</dd></div></dl><CopyValue label="退回请求号" value={revision.return_request_id}/><div className="planning-confirm-reason"><b>完整退回原因</b><p>{revision.return_reason}</p></div>{revision.revision_response_version_id?<div className="planning-response-body"><b>工程修订回复 v{revision.response_version_no}</b><p>{revision.response_text}</p><dl><div><dt>操作者</dt><dd>{revision.response_created_by}</dd></div><div><dt>保存时间</dt><dd>{revision.response_created_at?formatShanghaiTime(revision.response_created_at):""}</dd></div><div><dt>正文 SHA-256</dt><dd><code>{revision.response_text_digest}</code></dd></div></dl>{revision.response_request_id?<CopyValue label="回复请求号" value={revision.response_request_id}/>:null}</div>:<p className="planning-warning">尚无已保存回复；生成 v2 保持禁用。</p>}{revision.successor_package_id?<p className="planning-terminal"><b>直接后继已存在：</b>Package ID {revision.successor_package_id}/v{revision.successor_package_version_no} · {statusLabel(revision.successor_status)}</p>:null}</section>:null}
  {editable?<section className="planning-card planning-revision-editor"><p className="planning-kicker">修订回复草稿</p><h3>工程修订回复</h3><p>仅补充本次退回要求；源 v{detail.header.package_version_no}、Product/BOM、Unit Resolution 与物料快照全部只读。正文按 Unicode NFC 与 LF 换行保存，不转换中文全角标点。</p><form className="planning-form" onSubmit={saveResponse}><label htmlFor={`revision-response-${detail.header.id}`}>回复正文（必填，10—2000 字符）<textarea id={`revision-response-${detail.header.id}`} required minLength={10} maxLength={2000} value={responseText} onChange={event=>setResponseText(event.target.value)} placeholder="填写对计划部退回的完整工程修订回复"/></label><small className={responseLength>=10&&responseLength<=2000?"planning-char-count":"planning-char-count warning"}>{responseLength}/2000 字符</small><div className="planning-actions"><button type="submit" disabled={busy||responseLength<10||responseLength>2000||!dirty}>{busy?"正在保存…":saved?"保存新的回复版本":"保存回复草稿"}</button><button type="button" className="planning-secondary" disabled={busy||!saved||dirty||Boolean(revision?.successor_package_id)} onClick={()=>setConfirm(true)}>生成 v{detail.header.package_version_no+1}</button></div>{dirty&&saved?<p className="planning-warning">当前输入尚未保存；生成 v2 前须先保存为新的回复版本。</p>:null}</form><div className="planning-fixed-reuse"><h4>v{detail.header.package_version_no+1} 固定复用（只读）</h4>{detail.items.map(item=><article key={item.id}><b>{item.product_code} {item.product_version_code} · {item.bom_code} {item.bom_version_code}</b><span>Unit Resolution v{item.unit_resolution_version_no} · 需求 {compactNumber(item.required_quantity)} {item.unit_code} · {item.bom_lines.length} 项物料</span></article>)}</div>{notice?<State>{notice}</State>:null}{error?<State error>{error}</State>:null}</section>:null}
  {confirm&&revision?.revision_response_version_id?<SuccessorDialog detail={detail} revision={revision} busy={busy} onCancel={()=>setConfirm(false)} onConfirm={()=>void generateSuccessor()}/>:null}
 </>
}

function RevisionLineageCard({detail}:{detail:PackageDetail}){
 const lineage=detail.lineage!;const headAdvanced=Boolean(lineage.current_response_head_version&&lineage.current_response_head_version!==lineage.response_version_no);
 return <section className="planning-card planning-lineage-card" aria-label="完整修订谱系"><p className="planning-kicker">固定修订谱系</p><h3>v{lineage.previous_package_version_no} → 计划部退回 → 工程回复 → v{detail.header.package_version_no}</h3><div className="planning-lineage-flow"><span>Package ID {lineage.previous_package_id}/v{lineage.previous_package_version_no}</span><b>→</b><span>退回事件 {lineage.return_event_id}</span><b>→</b><span>回复 ID {lineage.revision_response_version_id}/v{lineage.response_version_no}</span><b>→</b><span>Package ID {detail.header.id}/v{detail.header.package_version_no}</span></div><div className="planning-confirm-reason"><b>计划部完整退回原因</b><p>{lineage.return_reason}</p></div><div className="planning-response-body"><b>固定工程回复 v{lineage.response_version_no}</b><p>{lineage.response_text}</p><dl><div><dt>回复操作者</dt><dd>{lineage.response_created_by}</dd></div><div><dt>回复时间</dt><dd>{formatShanghaiTime(lineage.response_created_at)}</dd></div><div><dt>正文 SHA-256</dt><dd><code>{lineage.response_text_digest}</code></dd></div></dl><CopyValue label="退回请求号" value={lineage.return_request_id}/><CopyValue label="回复请求号" value={lineage.response_request_id}/></div>{headAdvanced?<p className="planning-warning">当前回复版本头已推进至 v{lineage.current_response_head_version}；本 Package 仍固定引用 v{lineage.response_version_no}，不会随版本头改变。</p>:<p className="planning-gate-evidence">Package 摘要与关系外键固定绑定源 Package、退回事件、回复版本/正文摘要及 Product/BOM/Unit/物料快照。</p>}</section>
}

function SuccessorDialog({detail,revision,busy,onCancel,onConfirm}:{detail:PackageDetail;revision:RevisionContext;busy:boolean;onCancel:()=>void;onConfirm:()=>void}){
 return <div className="planning-dialog-backdrop"><section className="planning-dialog planning-successor-dialog" role="dialog" aria-modal="true" aria-labelledby="planning-successor-title"><p className="planning-kicker">后继版本确认</p><h2 id="planning-successor-title">确认生成 v{detail.header.package_version_no+1}</h2><dl className="planning-facts"><div><dt>源交接包</dt><dd>ID {detail.header.id}/v{detail.header.package_version_no}</dd></div><div><dt>退回事件</dt><dd>ID {revision.return_event_id}</dd></div><div><dt>工程回复</dt><dd>ID {revision.revision_response_version_id}/v{revision.response_version_no}</dd></div><div><dt>生成状态</dt><dd>{statusLabel("DRAFT")}</dd></div></dl><div className="planning-confirm-reason"><b>完整退回原因</b><p>{revision.return_reason}</p></div><div className="planning-response-body"><b>将固定引用的工程回复</b><p>{revision.response_text}</p></div><div className="planning-fixed-reuse"><h4>固定复用版本与快照</h4>{detail.items.map(item=><article key={item.id}><b>产品 {item.product_version_code} · BOM {item.bom_version_code} · 单位解析 v{item.unit_resolution_version_no}</b><span>{item.bom_lines.map(line=>`物料 ${line.material_id}: ${compactNumber(line.calculated_gross_quantity)} ${line.unit_code}`).join("；")}</span></article>)}</div><p>确认后将原子创建 v{detail.header.package_version_no+1} 草稿、创建事件和完整固定谱系；不会修改 v{detail.header.package_version_no}，也不会自动提交计划部。</p><div className="planning-dialog-actions"><button type="button" className="planning-secondary" disabled={busy} onClick={onCancel}>取消</button><button type="button" disabled={busy} onClick={onConfirm}>{busy?"正在生成…":`确认生成 v${detail.header.package_version_no+1}`}</button></div></section></div>
}
